export function createPool(n) { return { free: Array.from({length: n}, (_, i) => i), age: new Float32Array(n), live: new Set() }; }
export function spawn(p, k) { for (let i = 0; i < k; i++) { const idx = p.free.pop(); if (idx === undefined) throw new Error('pool exhausted'); p.age[idx] = 0; p.live.add(idx); } }
export function step(p, dt, life) { for (const idx of p.live) { p.age[idx] += dt; if (p.age[idx] >= life) { p.live.delete(idx); } } }

