import { describe, it, expect } from 'vitest';
import { createPool, spawn, step } from '../src/confetti.js';

describe('confetti pool', () => {
  it('demonstrates the leak: expired indices are never recycled', () => {
    const n = 100;
    const p = createPool(n);

    spawn(p, 60);
    expect(p.live.size).toBe(60);
    expect(p.free.length).toBe(40);

    // everything expires
    step(p, 1, 0.5);
    expect(p.live.size).toBe(0);
    // BUG: free is still 40 — the 60 expired indices are lost

    // second burst of 60 should succeed on a recycling pool...
    // on the leaked pool only 40 are available, so this throws
    expect(() => spawn(p, 60)).toThrow();
  });

  it('maintains the invariant free.length + live.size === n across bursts and expiry', () => {
    const n = 100;
    const p = createPool(n);

    for (let cycle = 0; cycle < 500; cycle++) {
      spawn(p, 60);          // burst
      step(p, 1, 0.5);       // expire everything
      expect(p.free.length + p.live.size).toBe(n);
      expect(p.free.length).toBe(n);
      expect(p.live.size).toBe(0);
    }
  });

  it('resets age when a recycled index respawns', () => {
    const n = 10;
    const p = createPool(n);

    spawn(p, 10);
    step(p, 0.25, 0.5);
    // all indices aged to 0.25, none expired yet
    expect(p.live.size).toBe(10);

    step(p, 0.3, 0.5); // everyone expires now
    expect(p.live.size).toBe(0);

    spawn(p, 10); // recycle all indices
    for (const idx of p.live) {
      expect(p.age[idx]).toBe(0);
    }
  });
});

